/**
 * Shop name board: a solid board x0..x1, y0..y1 at plane z (red_nether_bricks by default), with the name in banner
 * letters on the plane in front of it (z - 1, facing north, read left to right from the street). The letters go
 * only on air; they never replace a block. material: the board block; null keeps the wall as the board.
 */
export function fascia(g, x0, x1, y0, y1, z, name, material = "red_nether_bricks", opts = {}) {
  const lo = Math.min(x0, x1), hi = Math.max(x0, x1), bot = Math.min(y0, y1), top = Math.max(y0, y1);
  const { out, put } = writer();
  if (material) for (let x = lo; x <= hi; x++) for (let y = bot; y <= top; y++) put(g, x, y, z, material, undefined, opts);
  // plaque's north frame runs its u axis west, so the band's origin is its east end (hi), at the bottom row. Its
  // banners hang one cell out from `at` on the board plane z, so letters land on z - 1 (in front of the board)
  const plan = plaque(g, name, {
    at: [hi, bot, z], face: "north", width: hi - lo + 1, height: top - bot + 1,
    material: null, style: "banner", avoid: (p) => !AIRY.has(g.blockAt(...p)),
  });
  // letter cells plaque could not place (not air, outside the grid) are counted here; plaque's notes say why
  return { placed: out.placed + (plan?.cells ?? 0), refused: out.refused, letterSkips: plan?.skipped ?? 0, notes: plan?.notes ?? [] };
}

/**
 * Hood over a door or window: a bottom `dark_oak_slab` row x0..x1 at (y, z), carried on upside-down `dark_oak_stairs`
 * at both ends (y - 1, backs into the wall). Two hanging lanterns sit under the slab's inner cells; each hangs from
 * the slab above it. (plan.md puts the lanterns at the ends in front of the wall; the ends carry the stairs, so the
 * lanterns go to the next cells in, where a block is above them.) facing: the way the hood projects, e.g. "north".
 */
  for (const [x, y, z] of cellsOf(b)) {
    if (open.some((o) => inside(o, x, y, z))) continue;
    w.put(x, y, z, plinth && y < b[1] + 2 ? "polished_deepslate" : "bricks");
  }
  return done(w);
}

// A shop pilaster: stripped dark oak log to y1 - 1, a dark oak planks capital at y1, and an upside-down dark oak
// stair on the capital's street side (front = the street direction, the stair's lip points that way).
export function pilaster(g, x, z, { y0 = 5, y1 = 12, front = "north" } = {}) {
  const dz = DIRS[front][2], w = writer(g, norm([x, y0, z, x, y1, z + dz]));
  for (let y = y0; y < y1; y++) w.put(x, y, z, B.log("stripped_dark_oak", "y"));
  w.put(x, y1, z, B.block("dark_oak_planks"));
  w.put(x, y1, z + dz, B.stairs("dark_oak", OPPOSITE[front], "top"));
  return done(w);
}

// A hanging shop sign: a dark oak fence arm at y + 1 from (x, z) back to (x, z + 1) (joins the pilaster at x - 1),
// and the hanging sign below the arm's front end. rotation 8 faces north, the street.
export function hangingSign(g, x, z, y, text, { rotation = 8 } = {}) {
  const lines = Array.isArray(text) ? text : [text];
  const arm = [[x, y + 1, z], [x, y + 1, z + 1]], w = writer(g, norm([x, y, z, x, y + 1, z + 1]));
  for (const [ax, ay, az] of arm) w.put(ax, ay, az, ["dark_oak_fence", {}]);
  w.put(x, y, z, B.sign("dark_oak", lines, { wall: false, hanging: true, rotation, dataVersion: g.dataVersion }));
  linkFences(g, arm, "dark_oak");
  return done(w);
}

// A pair of open dark oak trapdoors either side of a window: x = the window's west column, y = its bottom row, z = the
 * sockets.json "display" for one socket: the inert blocks the shop shows, as an array or a "a,b,c" string. Rewrites the
 * file in place (1-space indent, as sockets.mjs writes it) and touches no other key. The socket must exist.
 * Returns the stored display string.
 */
export function setDisplay(socket, blocks, file = "sockets.json") {
  const layout = JSON.parse(readFileSync(file, "utf8"));
  if (!layout.sockets?.some((s) => s.id === socket)) throw new Error(`setDisplay: no socket ${socket} in ${file}`);
  const list = Array.isArray(blocks) ? blocks : String(blocks).split(",");
  layout.display = { ...(layout.display ?? {}), [socket]: list.join(",") };
  writeFileSync(file, JSON.stringify(layout, null, 1));
  return layout.display[socket];
}

/**
 * First-floor hearth on a wall. Firebox: two cells wide, two high, one deep, in the room's edge column. (x, z) is the
 * first column (lower x, or lower z for a north/south-running wall); facing is the way the fire opens into the room
 * (west for the east wall). Stone floor at row y, a lit campfire on it at row y+1, a stone hob beside the fire, and an
 * upside-down brick_stairs lintel at y+2 whose back is on the wall. The flue belongs to the chimney part. The two cells
 * in front of the firebox (rows y and y+1) are the lane and are never written. opts.room = [x0, y0, z0, x1, y1, z1]:
 * when given, the firebox and lane must sit inside it and the lane must be clear, or nothing is written.
 * Plan: x 18, z 13..14, y 14 (living room).
 */
1:  wall([4, 5, 6, 4, 12, 21]); wall([4, 13, 6, 4, 23, 21], false);   // west
3:  wall([4, 5, 22, 19, 12, 22]); wall([4, 13, 22, 19, 23, 22], false); // rear
4:  wall([4, 5, 23, 4, 12, 29]); wall([4, 13, 23, 4, 18, 29], false);   // wing west
6:  wall([4, 5, 30, 11, 12, 30]); wall([4, 13, 30, 11, 18, 30], false);   // wing south
13:  part([9, 14, 7, 9, 17, 21], [[9, 14, 12, 9, 15, 12], [9, 14, 18, 9, 15, 18]]); // first floor hall wall
16:  part([10, 19, 14, 18, 22, 14], [[11, 19, 14, 11, 20, 14], [16, 19, 14, 16, 20, 14]]); // corridor / children
17:  part([14, 19, 15, 14, 22, 21]);                                             // child A / B
19:  aislePartition(g, [14, 18], 19, { y0: 5, y1: 12 });
28:  for (const z of [9, 18]) for (const y of [14, 19]) { O(4, y, z, 4, y + 2, z); row(4, 4, y + 3, z - 1, z + 1); }
37:  O(4, 14, 26, 4, 16, 27); row(4, 4, 17, 25, 28);
40:  for (const y of [18, 23]) { row(4, 19, y, 5, 5); row(4, 19, y, 22, 22); row(4, 4, y, 6, 21); row(19, 19, y, 6, 21); }
41:  row(4, 4, 18, 23, 30); row(11, 11, 18, 23, 30); row(4, 11, 18, 30, 30);
60:  wall([4, 5, 6, 4, 12, 21]); wall([4, 13, 6, 4, 23, 21], false);   // west
63:  wall([4, 5, 23, 4, 12, 29]); wall([4, 13, 23, 4, 18, 29], false);   // wing west

