const BANNER_LETTER = {
  A: ["stripe_left", "stripe_right", "stripe_top", "stripe_middle"], B: ["stripe_left", "stripe_top", "stripe_middle", "stripe_bottom", "stripe_right", "curly_border*"],
  C: ["stripe_left", "stripe_top", "stripe_bottom"], D: ["stripe_right", "stripe_bottom", "stripe_top", "curly_border*", "stripe_left"],
  E: ["stripe_left", "stripe_top", "stripe_middle", "stripe_bottom"], F: ["stripe_left", "stripe_top", "stripe_middle"],
  G: ["stripe_right", "half_horizontal*", "stripe_bottom", "stripe_left", "stripe_top"], H: ["stripe_left", "stripe_right", "stripe_middle"],
  I: ["stripe_center", "stripe_top", "stripe_bottom"], J: ["stripe_left", "half_horizontal*", "stripe_bottom", "stripe_right"],
  K: ["stripe_downright", "half_horizontal*", "stripe_downleft", "stripe_left"], L: ["stripe_bottom", "stripe_left"],
  M: ["triangle_top", "triangles_top*", "stripe_left", "stripe_right"], N: ["stripe_left", "triangle_top*", "stripe_downright", "stripe_right"],
  O: ["stripe_left", "stripe_right", "stripe_top", "stripe_bottom"], P: ["stripe_right", "half_horizontal_bottom*", "stripe_middle", "stripe_top", "stripe_left"],
  Q: ["stripe_left", "stripe_right", "stripe_top", "stripe_bottom", "square_bottom_right"], R: ["half_horizontal", "stripe_center*", "stripe_top", "stripe_left", "stripe_downright"],
  S: ["stripe_top", "stripe_downright", "stripe_bottom"], T: ["stripe_top", "stripe_center"], U: ["stripe_left", "stripe_right", "stripe_bottom"],
  V: ["stripe_left", "triangle_bottom*", "stripe_downleft"], W: ["triangle_bottom", "triangles_bottom*", "stripe_left", "stripe_right"],
  X: ["cross"], Y: ["stripe_downright", "half_horizontal_bottom*", "stripe_downleft"], Z: ["stripe_top", "stripe_downleft", "stripe_bottom"],
  0: ["stripe_left", "stripe_right", "stripe_top", "stripe_bottom", "stripe_downleft"], 1: ["stripe_center", "square_top_left", "stripe_bottom"],
  2: ["stripe_top", "stripe_downleft", "stripe_bottom"], 3: ["stripe_bottom", "stripe_middle", "stripe_top", "curly_border*", "stripe_right"],
  4: ["stripe_left", "half_horizontal_bottom*", "stripe_right", "stripe_middle"], 5: ["stripe_bottom", "stripe_downright", "stripe_top"],
  6: ["stripe_bottom", "stripe_right", "half_horizontal*", "stripe_middle", "stripe_left"], 7: ["stripe_downleft", "stripe_top"],
  8: ["stripe_top", "stripe_left", "stripe_middle", "stripe_bottom", "stripe_right"], 9: ["stripe_left", "half_horizontal_bottom*", "stripe_middle", "stripe_top", "stripe_right"],
  "&": ["stripe_middle", "stripe_center", "rhombus"], "-": ["stripe_middle"],
};
/** Banner patterns for a character: letter dye on base dye; "*" layers are drawn in the base dye (to cut back), and a
 *  base-coloured border closes every letter so neighbouring banners read as separate characters. */
export function bannerLetter(ch, letterDye, baseDye) {
  const r = BANNER_LETTER[String(ch).toUpperCase()];
  if (!r) return null;
  return [...r.map((p) => (p.endsWith("*") ? [p.slice(0, -1), baseDye] : [p, letterDye])), ["border", baseDye]];
}
